-- ============================================================================
-- superi.ge — პროდუქტების ახალი SEO აღწერები (meta description) შენი Excel-იდან
-- (12-meta-descriptions-instock-fixed.xlsx). იცვლება მხოლოდ meta description:
-- 1132 პროდუქტი, ქართული (ka). სხვა ველს და სხვა პროდუქტს არ ეხება.
-- პროდუქტი იძებნება კოდით და ID-ით ერთად, ასე რომ სხვა პროდუქტი ვერ შეიცვლება.
-- ძველი აღწერები ინახება ცხრილში superi_bk_meta_13 (დაბრუნება: ბოლოში).
-- გამოტოვებულია S21897 (product-14040): სახელი არ აქვს, Excel-ში შენიშვნა ეწერა.
-- ============================================================================

SET NAMES utf8mb4;
DROP TEMPORARY TABLE IF EXISTS tmp_meta;
-- ცხრილის სვეტები იგივე ტიპისაა, რაც საიტის ბაზაში (კოდირების შეუსაბამობა არ იქნება)
CREATE TEMPORARY TABLE tmp_meta AS SELECT p.product_id AS pid, p.product_code AS code, pd.meta_description AS meta FROM cscart_products p JOIN cscart_product_descriptions pd ON pd.product_id = p.product_id LIMIT 0;


-- 1) ძველი აღწერების ასლი (მხოლოდ პირველ გაშვებაზე)
CREATE TABLE IF NOT EXISTS superi_bk_meta_13 AS SELECT pd.product_id, pd.lang_code, pd.meta_description FROM cscart_product_descriptions pd JOIN tmp_meta t ON t.pid = pd.product_id WHERE pd.lang_code = 'ka';

-- 2) ახალი აღწერა: მხოლოდ თუ ID-იც და კოდიც ემთხვევა
UPDATE cscart_product_descriptions pd JOIN cscart_products p ON p.product_id = pd.product_id JOIN tmp_meta t ON t.pid = p.product_id AND (t.code = p.product_code OR t.code = '') SET pd.meta_description = t.meta WHERE pd.lang_code = 'ka';

-- 3) შედეგი: rows_in_file = ფაილში, updated_ok = ახლა სწორი აღწერა აქვს, not_matched = კოდი/ID ვერ დაემთხვა
SELECT (SELECT COUNT(*) FROM tmp_meta) AS rows_in_file, (SELECT COUNT(*) FROM cscart_product_descriptions pd JOIN tmp_meta t ON t.pid = pd.product_id AND pd.meta_description = t.meta WHERE pd.lang_code = 'ka') AS updated_ok, (SELECT IFNULL(GROUP_CONCAT(t.code SEPARATOR ', '), '-') FROM tmp_meta t LEFT JOIN cscart_products p ON p.product_id = t.pid AND (p.product_code = t.code OR t.code = '') WHERE p.product_id IS NULL) AS not_matched;
DROP TEMPORARY TABLE IF EXISTS tmp_meta;

